// base-repo-standard's audit against throwaway repositories built from its own assets: the assets as given must pass,
// and each realistic way of getting the base wrong must fail the check that names it. Offline (no GitHub settings);
// needs `mise` and the network (the pinned tools, once; osv-scanner's vulnerability database). The token probe is
// generated by the audit at run time, so this file carries none.
import { describe, expect, test } from "bun:test";
import { chmodSync, cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

const SKILL = join(import.meta.dir, "../skills/base-repo-standard");
const ASSETS = join(SKILL, "assets");
const TIMEOUT = 180_000;

interface Result {
	failed: number;
	checks: { id: string; status: string; detail: string }[];
}

function sh(cmd: string[], cwd: string) {
	const p = Bun.spawnSync(cmd, { cwd, stdout: "pipe", stderr: "pipe" });
	if (p.exitCode !== 0) throw new Error(`${cmd.join(" ")}: ${p.stderr}`);
	return p.stdout.toString();
}

function write(dir: string, file: string, text: string, mode?: number) {
	mkdirSync(dirname(join(dir, file)), { recursive: true });
	writeFileSync(join(dir, file), text);
	if (mode) chmodSync(join(dir, file), mode);
}

const ciWorkflow = () =>
	`name: ci\non: [push, pull_request]\npermissions:\n  contents: read\njobs:\n${readFileSync(join(ASSETS, "ci-base.yml"), "utf8")}`;
const extending = (...presets: string[]) =>
	JSON.stringify({
		extends: ["local>pitolabs/renovate-config", ...presets.map((p) => `local>pitolabs/renovate-config:${p}`)],
	});

/** A repository set up as the assets say, changed by `mutate`, committed; then audited. */
function audit(mutate: (dir: string) => void = () => {}, behavior = true): Result {
	const base = mkdtempSync(join(tmpdir(), "audit-base-fixture-"));
	const dir = join(base, "repo");
	try {
		for (const f of ["mise.toml", "mise.lock", "renovate.json", ".githooks/pre-commit", "scripts/setup.sh"]) {
			mkdirSync(dirname(join(dir, f)), { recursive: true });
			cpSync(join(ASSETS, f), join(dir, f));
		}
		write(dir, ".github/workflows/ci.yml", ciWorkflow());
		write(dir, "README.md", "# fixture\n");
		mutate(dir);
		sh(["git", "init", "-q", "-b", "main"], dir);
		sh(["git", "config", "user.email", "1+fixture@users.noreply.github.com"], dir);
		sh(["git", "config", "user.name", "fixture"], dir);
		sh(["git", "add", "-A"], dir);
		sh(["git", "commit", "-q", "--no-verify", "-m", "fixture"], dir);
		const flags = ["--offline", "--json", ...(behavior ? [] : ["--no-behavior"])];
		const p = Bun.spawnSync(["bun", join(SKILL, "scripts/audit.ts"), dir, ...flags], {
			stdout: "pipe",
			stderr: "pipe",
		});
		if (p.exitCode !== 0 && p.exitCode !== 1) throw new Error(`audit exited ${p.exitCode}: ${p.stderr}`);
		return JSON.parse(p.stdout.toString());
	} finally {
		rmSync(base, { recursive: true, force: true });
	}
}

const check = (r: Result, id: string) => r.checks.find((c) => c.id === id);
const failing = (r: Result) => r.checks.filter((c) => c.status === "fail").map((c) => `${c.id}: ${c.detail}`);

describe("base-repo-standard audit", () => {
	test(
		"the assets as given pass: the checks run clean and the hook commits a clean change but refuses a token",
		() => {
			const r = audit();
			expect(failing(r)).toEqual([]);
			for (const id of ["run.secrets", "run.workflows", "run.shell", "run.vulns", "ci.base-job", "mise.lock"])
				expect(check(r, id)?.status).toBe("pass");
			expect(check(r, "hook.secrets")?.detail).toBe("a clean change: committed; a GitHub token: refused");
		},
		TIMEOUT,
	);

	test(
		"a pre-commit hook without gitleaks commits a token",
		() => {
			const r = audit((dir) => write(dir, ".githooks/pre-commit", "#!/bin/sh\nexit 0\n", 0o755));
			expect(check(r, "hook.secrets")?.status).toBe("fail");
			expect(check(r, "hook.secrets")?.detail).toContain("a GitHub token: COMMITTED");
		},
		TIMEOUT,
	);

	test(
		"the workflow check accepts current runner labels and refuses an unquoted shell variable in a run step",
		() => {
			const newRunner = audit((dir) =>
				write(dir, ".github/workflows/ci.yml", ciWorkflow().replaceAll("ubuntu-24.04", "ubuntu-26.04")),
			);
			expect(check(newRunner, "run.workflows")?.status).toBe("pass");
			const unquoted = audit((dir) =>
				write(
					dir,
					".github/workflows/ci.yml",
					`${ciWorkflow()}  echo:\n    runs-on: ubuntu-24.04\n    steps:\n      - run: echo $HOME\n`,
				),
			);
			expect(check(unquoted, "run.workflows")?.status).toBe("fail");
			expect(check(unquoted, "run.workflows")?.detail).toContain("SC2086");
		},
		TIMEOUT,
	);

	test(
		"a lockfile with a known-vulnerable dependency fails the vulnerability check",
		() => {
			const lockfile = {
				name: "fixture",
				version: "1.0.0",
				lockfileVersion: 3,
				requires: true,
				packages: {
					"": { name: "fixture", version: "1.0.0", dependencies: { lodash: "4.17.20" } },
					"node_modules/lodash": {
						version: "4.17.20",
						resolved: "https://registry.npmjs.org/lodash/-/lodash-4.17.20.tgz",
					},
				},
			};
			const r = audit((dir) => write(dir, "package-lock.json", JSON.stringify(lockfile, null, 2)));
			expect(check(r, "run.vulns")?.status).toBe("fail");
			expect(check(r, "run.vulns")?.detail).toContain("lodash");
		},
		TIMEOUT,
	);

	test("without renovate.json, Renovate never runs on the shared preset", () => {
		const r = audit((dir) => rmSync(join(dir, "renovate.json")), false);
		expect(check(r, "renovate.config")?.status).toBe("fail");
	});

	test("automerge without tests on pull requests fails until CI runs them", () => {
		const automerge = (dir: string) => write(dir, "renovate.json", extending("automerge"));
		const untested = audit(automerge, false);
		expect(check(untested, "renovate.automerge")?.status).toBe("fail");
		const tested = audit((dir) => {
			automerge(dir);
			write(
				dir,
				".github/workflows/ci.yml",
				`${ciWorkflow()}  test:\n    runs-on: ubuntu-24.04\n    steps:\n      - run: bun test\n`,
			);
		}, false);
		expect(check(tested, "renovate.automerge")?.status).toBe("pass");
		// The same test step in a workflow that never runs on pull requests does not count.
		const pushOnly = audit((dir) => {
			automerge(dir);
			write(
				dir,
				".github/workflows/ci.yml",
				`${ciWorkflow().replace("[push, pull_request]", "[push]")}  test:\n    runs-on: ubuntu-24.04\n    steps:\n      - run: bun test\n`,
			);
		}, false);
		expect(check(pushOnly, "renovate.automerge")?.status).toBe("fail");
	});

	test("an action pinned by tag fails, a SHA-pinned one passes", () => {
		const r = audit(
			(dir) =>
				write(
					dir,
					".github/workflows/ci.yml",
					ciWorkflow().replace(/actions\/checkout@[0-9a-f]{40} # v7\.0\.1/, "actions/checkout@v7.0.1"),
				),
			false,
		);
		expect(check(r, "ci.pinned-actions")?.status).toBe("fail");
		expect(check(r, "ci.pinned-actions")?.detail).toContain("actions/checkout@v7.0.1");
		expect(
			check(
				audit(() => {}, false),
				"ci.pinned-actions",
			)?.status,
		).toBe("pass");
	});

	test("a workflow without top-level permissions, or with a top-level write, fails", () => {
		const none = audit(
			(dir) => write(dir, ".github/workflows/ci.yml", ciWorkflow().replace("permissions:\n  contents: read\n", "")),
			false,
		);
		expect(check(none, "ci.permissions")?.status).toBe("fail");
		const writes = audit(
			(dir) => write(dir, ".github/workflows/ci.yml", ciWorkflow().replace("contents: read", "contents: write")),
			false,
		);
		expect(check(writes, "ci.permissions")?.status).toBe("fail");
	});

	test("a tool bumped in mise.toml without regenerating mise.lock fails the lock check", () => {
		const r = audit((dir) => {
			const toml = readFileSync(join(dir, "mise.toml"), "utf8");
			write(dir, "mise.toml", toml.replace(/("aqua:zizmorcore\/zizmor" = )"[^"]+"/, '$1"1.31.0"'));
		}, false);
		expect(check(r, "mise.config")?.status).toBe("pass");
		expect(check(r, "mise.lock")?.status).toBe("fail");
		expect(check(r, "mise.lock")?.detail).toContain("aqua:zizmorcore/zizmor 1.31.0 not locked");
	});

	test("an osv-scanner ignore needs an expiry within 90 days and a reason", () => {
		const day = (offset: number) => new Date(Date.now() + offset * 86_400_000).toISOString().slice(0, 10);
		const entry = (until: string) => `[[IgnoredVulns]]\nid = "GHSA-aaaa-bbbb-cccc"\n${until}reason = "pending"\n`;
		const noExpiry = audit((dir) => write(dir, "osv-scanner.toml", entry("")), false);
		expect(check(noExpiry, "baseline.osv")?.status).toBe("fail");
		expect(check(noExpiry, "baseline.osv")?.detail).toContain("no ignoreUntil");
		const tooLate = audit((dir) => write(dir, "osv-scanner.toml", entry(`ignoreUntil = ${day(120)}\n`)), false);
		expect(check(tooLate, "baseline.osv")?.status).toBe("fail");
		const dated = audit((dir) => write(dir, "osv-scanner.toml", entry(`ignoreUntil = ${day(30)}\n`)), false);
		expect(check(dated, "baseline.osv")?.status).toBe("pass");
	});
});
